Input: {"question": "When did Cosimo de' Medici become Grand Duke of Tuscany?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 0, "end": 150, "text": "Cosimo II de' Medici, Grand Duke of Tuscany Cosimo II de' Medici (12 May 1590 – 28 February 1621) was Grand Duke of Tuscany from 1609 until his death."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 151, "end": 249, "text": "He was the elder son of Ferdinando I de' Medici, Grand Duke of Tuscany, and Christina of Lorraine."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 250, "end": 353, "text": "For the majority of his twelve-year reign, he delegated the administration of Tuscany to his ministers."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 354, "end": 430, "text": "He is best remembered as the patron of Galileo Galilei, his childhood tutor."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 431, "end": 509, "text": "Cosimo's father Ferdinando I took care to provide him with a modern education."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 510, "end": 575, "text": "Indeed, Galileo Galilei was Cosimo's tutor between 1605 and 1608."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0341-0296b4a3f7dd:d00", "start": 576, "end": 586, "text": "Ferdinando"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 0, "end": 31, "text": "Embodying Meaning and Emotion ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 32, "end": 39, "text": "Brill ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 40, "end": 44, "text": "pp ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 45, "end": 55, "text": "162– 185 ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 56, "end": 74, "text": "Crews , Daniel A ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 75, "end": 85, "text": "( 2008 ) ."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 86, "end": 144, "text": "Twilight of the Renaissance : The Life of Juan de Valdés ."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 145, "end": 174, "text": "University of Toronto Press ."}, "D2S9": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 175, "end": 203, "text": "Davies , Jonathan ( 2009 ) ."}, "D2S10": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 204, "end": 264, "text": "Culture and Power : Tuscany and Its Universities 1537-1609 ."}, "D2S11": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 265, "end": 272, "text": "Brill ."}, "D2S12": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 273, "end": 304, "text": "Fletcher , Catherine ( 2016 ) ."}, "D2S13": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 305, "end": 406, "text": "The Black Prince of Florence : The Spectacular Life and Treacherous World of Alessandro De ' Medici ."}, "D2S14": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 407, "end": 432, "text": "Oxford University Press ."}, "D2S15": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 433, "end": 458, "text": "Fossi , Gloria ( 2001 ) ."}, "D2S16": {"document_number": 2, "doc_id": "ramdocs-0341-0296b4a3f7dd:d01", "start": 459, "end": 491, "text": "Uffizi Gallery : Art , History ,"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0341-0296b4a3f7dd:d02", "start": 0, "end": 9, "text": "in 1621 ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0341-0296b4a3f7dd:d02", "start": 10, "end": 71, "text": "Callot visually documented feasts and carnivals in Florence ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0341-0296b4a3f7dd:d02", "start": 72, "end": 526, "text": "Carnaval te Florence infanteriegevecht , RP-P-OB-20.859 Carnaval te Florence praalwagens en deelnemers aan de optocht , RP-P-OB-20.860 Issue [ edit ] Maria Cristina de ' Medici ( 24 August 1609 – 9 August 1632 ) , died unmarried [ 8 ] Ferdinando II de ' Medici , Grand Duke of Tuscany ( 14 July 1610 – 23 May 1670 ) , who married Vittoria della Rovere and had issue Gian Carlo de ' Medici ( 24 July 1611 – 23 January 1663 ) , died unmarried Margherita de"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0341-0296b4a3f7dd:d03", "start": 0, "end": 228, "text": "Cosimo I de' Medici, Grand Duke of Tuscany Cosimo I de' Medici (12 June 1519 – 21 April 1574) was the second Duke of Florence from 1537 until 1569, when he became the first Grand Duke of Tuscany, a title he held until his death."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0341-0296b4a3f7dd:d03", "start": 229, "end": 393, "text": "Cosimo was born in Florence on 12 June 1519, the son of the famous condottiere Ludovico de' Medici (known as Giovanni dalle Bande Nere) and his wife Maria Salviati."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0341-0296b4a3f7dd:d03", "start": 394, "end": 474, "text": "He was the grandson of Caterina Sforza, the Countess of Forlì and Lady of Imola."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0341-0296b4a3f7dd:d03", "start": 475, "end": 525, "text": "Cosimo came to power in 1537 at age 17, just after"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 0, "end": 21, "text": "Tuscany ( 1569–74 ) ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 22, "end": 180, "text": "The son of Giovanni de ’ Medici , Cosimo became head of the Florentine republic in 1537 after the assassination of his distant cousin Alessandro de ’ Medici ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 181, "end": 292, "text": "He continued Alessandro ’ s tyrannical rule and defeated attempts to oust him with aid from Emperor Charles V ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 293, "end": 402, "text": "Seeking to expand his power , he attacked Siena in 1554 and brought nearly all of Tuscany under his control ."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 403, "end": 505, "text": "He used his despotic power to improve the government ’ s efficiency and to sponsor artistic projects ."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0341-0296b4a3f7dd:d04", "start": 506, "end": 537, "text": "Far advanced for the time as an"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 0, "end": 159, "text": "Cosimo III de' Medici, Grand Duke of Tuscany Cosimo III de' Medici (14 August 1642 – 31 October 1723) was the penultimate (sixth) Medici Grand Duke of Tuscany."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 160, "end": 240, "text": "He reigned from 1670 to 1723, and was the elder son of Grand Duke Ferdinando II."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 241, "end": 407, "text": "Cosimo's 53-year-long reign, the longest in Tuscan history, was marked by a series of ultra-reactionary laws which regulated prostitution and banned May celebrations."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 408, "end": 493, "text": "His reign also witnessed Tuscany's deterioration to previously unknown economic lows."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 494, "end": 575, "text": "He was succeeded by his elder surviving son, Gian Gastone, when he died, in 1723."}, "D6S6": {"document_number": 6, "doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "start": 576, "end": 624, "text": "He married Marguerite Louise d'Orléans, a cousin"}, "D7S1": {"document_number": 7, "doc_id": "ramdocs-0341-0296b4a3f7dd:d06", "start": 0, "end": 551, "text": "Peter Ferdinand * Prince Leopold Salvator * Prince Franz Salvator * 12th generation Prince Gottfried * Prince Rainer * Prince Leopold Maria * Prince Franz Joseph * Prince Karl Pius * Prince Franz Karl Salvator * Prince Hubert Salvator * 13th generation Prince Dominic * * also an archduke of Austria v t e Grand dukes of Tuscany Cosimo I ( 1569–1574 ) Francesco I ( 1574-1587 ) Ferdinando I ( 1587–1609 ) Cosimo II ( 1609–1621 ) Ferdinando II ( 1621–1670 ) Cosimo III ( 1670–1723 ) Gian Gastone ( 1723–1737 ) Francesco Stefano ( 1737-1765 ) Leopoldo I"}}, "original_cards": [{"doc_id": "ramdocs-0341-0296b4a3f7dd:d03", "card_id": "ramdocs-0341-0296b4a3f7dd:d03:c0", "entity": "Cosimo I de' Medici", "scope": "becoming Grand Duke of Tuscany", "claim": "Cosimo I de' Medici became the first Grand Duke of Tuscany in 1569.", "answer": "1569", "quote": "Cosimo I de' Medici, Grand Duke of Tuscany Cosimo I de' Medici (12 June 1519 – 21 April 1574) was the second Duke of Florence from 1537 until 1569, when he became the first Grand Duke of Tuscany, a title he held until his death.", "original_document_number": 4}, {"doc_id": "ramdocs-0341-0296b4a3f7dd:d05", "card_id": "ramdocs-0341-0296b4a3f7dd:d05:c0", "entity": "Cosimo III de' Medici", "scope": "Grand Duke of Tuscany", "claim": "Cosimo III de' Medici reigned as Grand Duke of Tuscany from 1670 to 1723.", "answer": "1670", "quote": "He reigned from 1670 to 1723, and was the elder son of Grand Duke Ferdinando II.", "original_document_number": 6}], "current_answers": ["1569", "1609", "1670"], "candidate_answers": [{"candidate_id": "R0", "answer": "1569", "origin": "initial"}, {"candidate_id": "R1", "answer": "1609", "origin": "coverage_addition"}, {"candidate_id": "R2", "answer": "1670", "origin": "coverage_addition"}]}

